function consultaEndereco(){var e=document.querySelector("#cep").value;8!==e.length&&alert("CEP invalido"),fetch(`https://viacep.com.br/ws/${e}/json/`).then(function(e){e.json().then(function(e){mostrarEndereco(e)})})}function mostrarEndereco(e){var t=document.querySelector("#resRua"),o=document.querySelector("#resBairro"),n=document.querySelector("#resLocalidade"),r=document.querySelector("#resUf");t.textContent=e.logradouro,o.textContent=e.bairro,n.textContent=e.localidade,r.textContent=e.uf}